<?php
require 'conexion.php';
$p=$_GET['p']??'inicio'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
 if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??''))throw new RuntimeException('Formulario vencido.');
 $a=$_POST['accion']??'';
 if($a==='login'){$u=q('SELECT * FROM usuarios WHERE correo=? AND activo=1',[trim($_POST['correo']??'')])->fetch();if(!$u||!password_verify($_POST['clave']??'',$u['clave']))throw new RuntimeException('Correo o contraseña incorrectos.');session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['nombre']=$u['nombre'];go();}
 if(empty($_SESSION['uid']))go('login');
 if($a==='salir'){session_destroy();go('login');}
 if($a==='guardar'){
 $id=entero($_POST['id']??0);$codigo=trim($_POST['codigo']??'');$nombre=trim($_POST['nombre']??'');$desc=trim($_POST['descripcion']??'');$cat=entero($_POST['categoria']??0,1);$precio=$_POST['precio']??'';$min=entero($_POST['minimo']??'');
 if(!$codigo||!$nombre||strlen($codigo)>50||strlen($nombre)>150||strlen($desc)>2000||!preg_match('/^\d{1,8}(\.\d{1,2})?$/',$precio)||!q('SELECT id FROM categorias WHERE id=? AND activo=1',[$cat])->fetch())throw new RuntimeException('Revisa los datos del producto.');
 if($id){q('UPDATE productos SET codigo=?,nombre=?,descripcion=?,categoria_id=?,precio=?,minimo=? WHERE id=? AND activo=1',[$codigo,$nombre,$desc,$cat,$precio,$min,$id]);}else{q('INSERT INTO productos(codigo,nombre,descripcion,categoria_id,precio,minimo,stock) VALUES(?,?,?,?,?,?,?)',[$codigo,$nombre,$desc,$cat,$precio,$min,entero($_POST['stock']??'')]);}
 $_SESSION['mensaje']='Producto guardado.';go('productos');}
 if($a==='desactivar'){q('UPDATE productos SET activo=0 WHERE id=?',[entero($_POST['id']??0,1)]);$_SESSION['mensaje']='Producto desactivado.';go('productos');}
 if($a==='movimiento'){$id=entero($_POST['producto']??0,1);$n=entero($_POST['cantidad']??0,1);$tipo=$_POST['tipo']??'';$obs=trim($_POST['observacion']??'');if(!in_array($tipo,['entrada','salida'],true)||strlen($obs)>255)throw new RuntimeException('Movimiento inválido.');$db->beginTransaction();$r=q('SELECT stock FROM productos WHERE id=? AND activo=1 FOR UPDATE',[$id])->fetch();if(!$r)throw new RuntimeException('Producto no disponible.');$nuevo=(int)$r['stock']+($tipo==='entrada'?$n:-$n);if($nuevo<0||$nuevo>2147483647)throw new RuntimeException('Stock insuficiente o fuera de rango.');q('UPDATE productos SET stock=? WHERE id=?',[$nuevo,$id]);q('INSERT INTO movimientos(producto_id,usuario_id,tipo,cantidad,observacion) VALUES(?,?,?,?,?)',[$id,$_SESSION['uid'],$tipo,$n,$obs]);$db->commit();$_SESSION['mensaje']='Movimiento registrado.';go('historial');}
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof PDOException?'No se pudo guardar. Revisa códigos duplicados y datos.':$e->getMessage();}
}
if(empty($_SESSION['uid']))$p='login';
$mensaje=$_SESSION['mensaje']??'';unset($_SESSION['mensaje']);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>TecnoStock</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/estilos.css"></head><body>
<?php if($p!=='login'): ?><nav><strong>TecnoStock <small> / Inventario</small></strong><div><?php foreach(['inicio'=>'Resumen','productos'=>'Productos','movimientos'=>'Movimientos','historial'=>'Historial'] as $k=>$v): ?><a class="<?= $p===$k?'selected':'' ?>" href="?p=<?=h($k)?>"><?=h($v)?></a><?php endforeach; ?></div><form method="post"><?=token()?><button name="accion" value="salir" class="btn btn-outline-light btn-sm">Salir</button></form></nav><?php endif; ?>
<main class="container py-4">
<?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif; if($mensaje):?><div class="alert alert-success"><?=h($mensaje)?></div><?php endif; ?>
<?php if($p==='login'): ?><section class="login card p-4"><p class="eyebrow">GESTIÓN DE EXISTENCIAS</p><h1>TecnoStock</h1><p>Acceso del encargado de inventario</p><form method="post"><?=token()?><label>Correo<input class="form-control" type="email" name="correo" required></label><label>Contraseña<input class="form-control" type="password" name="clave" required></label><button class="btn btn-primary w-100 mt-3" name="accion" value="login">Ingresar</button></form></section>
<?php elseif($p==='inicio'): $stats=q('SELECT COUNT(*) total,COALESCE(SUM(stock),0) unidades,COALESCE(SUM(stock<minimo),0) bajos FROM productos WHERE activo=1')->fetch();?><p class="eyebrow">OPERACIONES / RESUMEN</p><h1>Control de inventario</h1><p>Bienvenido, <?=h($_SESSION['nombre'])?>.</p><div class="metrics"><?php foreach(['Productos activos'=>$stats['total'],'Unidades disponibles'=>$stats['unidades'],'Requieren reposición'=>$stats['bajos'],'Movimientos'=>q('SELECT COUNT(*) FROM movimientos')->fetchColumn()] as $k=>$v):?><article class="card p-3"><span><?=h($k)?></span><b><?=h($v)?></b></article><?php endforeach;?></div><section class="card p-4 mt-4"><h2>Productos por reponer</h2><?php $rows=q('SELECT * FROM productos WHERE activo=1 AND stock<minimo ORDER BY stock')->fetchAll();if(!$rows)echo '<p>Sin alertas.</p>';foreach($rows as $r):?><p><?=h($r['nombre'])?> — <?=h($r['stock'])?> de <?=h($r['minimo'])?> mínimos <a href="?p=movimientos">Reponer</a></p><?php endforeach;?><a class="btn btn-primary" href="?p=productos">Administrar catálogo</a></section>
<?php elseif($p==='productos'): $buscar=trim($_GET['buscar']??'');$cat=(int)($_GET['cat']??0);$cats=q('SELECT * FROM categorias WHERE activo=1 ORDER BY nombre')->fetchAll();$rows=q('SELECT p.*,c.nombre categoria FROM productos p JOIN categorias c ON c.id=p.categoria_id WHERE p.activo=1 AND (p.nombre LIKE ? OR p.codigo LIKE ?) AND (?=0 OR p.categoria_id=?) ORDER BY p.nombre',["%$buscar%","%$buscar%",$cat,$cat])->fetchAll();?><div class="heading"><h1>Catálogo de productos</h1><a class="btn btn-primary" href="?p=editar">+ Registrar producto</a></div><form class="filters card p-3 my-3" method="get"><input type="hidden" name="p" value="productos"><input class="form-control" name="buscar" placeholder="Nombre o código" value="<?=h($buscar)?>"><select class="form-select" name="cat"><option value="0">Todas las categorías</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$cat==$c['id']?'selected':''?>><?=h($c['nombre'])?></option><?php endforeach;?></select><button class="btn btn-primary">Buscar</button></form><div class="card table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Código / producto</th><th>Categoría</th><th>Precio</th><th>Stock / mínimo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=h($r['nombre'])?></strong><small><?=h($r['codigo'])?> · <?=h($r['descripcion'])?></small></td><td><?=h($r['categoria'])?></td><td>$<?=number_format($r['precio'],0,',','.')?></td><td><?=$r['stock']?> / <?=$r['minimo']?></td><td><span class="badge <?=$r['stock']<$r['minimo']?'text-bg-warning':'text-bg-success'?>"><?=$r['stock']<$r['minimo']?'Stock bajo':'Disponible'?></span></td><td><a href="?p=editar&id=<?=$r['id']?>">Editar</a><form method="post" class="d-inline" onsubmit="return confirm('¿Desactivar producto?')"><?=token()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger" name="accion" value="desactivar">Desactivar</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p class="p-3">No hay resultados.</p><?php endif;?></div>
<?php elseif($p==='editar'): $id=(int)($_GET['id']??0);$r=$id?q('SELECT * FROM productos WHERE id=? AND activo=1',[$id])->fetch():['id'=>0,'codigo'=>'','nombre'=>'','descripcion'=>'','categoria_id'=>0,'precio'=>'','stock'=>0,'minimo'=>0];if(!$r){echo '<p>Producto no encontrado.</p>';}else{?><h1><?=$id?'Editar':'Registrar'?> producto</h1><form method="post" class="card p-4 formgrid" data-validar><?=token()?><input type="hidden" name="id" value="<?=$r['id']?>"><?php foreach(['codigo'=>'Código','nombre'=>'Nombre','precio'=>'Precio','minimo'=>'Stock mínimo','stock'=>'Stock actual'] as $k=>$v):?><label><?=h($v)?><input class="form-control" name="<?=$k?>" value="<?=h($r[$k])?>" <?=$k==='stock'&&$id?'readonly':''?> <?=in_array($k,['precio','minimo','stock'])?'type="number" min="0" step="'.($k==='precio'?'0.01':'1').'"':'maxlength="'.($k==='codigo'?50:150).'"'?> required></label><?php endforeach;?><label>Categoría<select class="form-select" name="categoria" required><option value="">Seleccionar</option><?php foreach(q('SELECT * FROM categorias WHERE activo=1')->fetchAll() as $c):?><option value="<?=$c['id']?>" <?=$r['categoria_id']==$c['id']?'selected':''?>><?=h($c['nombre'])?></option><?php endforeach;?></select></label><label class="wide">Descripción<textarea class="form-control" name="descripcion" maxlength="2000"><?=h($r['descripcion'])?></textarea></label><p class="wide">Para ajustar el stock de un producto existente, registra un movimiento.</p><div class="wide"><button class="btn btn-primary" name="accion" value="guardar">Guardar</button> <a href="?p=productos">Cancelar</a></div></form><?php } ?>
<?php elseif($p==='movimientos'):?><h1>Registrar movimiento</h1><form method="post" class="card p-4 formgrid" data-validar><?=token()?><label class="wide">Producto<select class="form-select" name="producto" required><option value="">Seleccionar</option><?php foreach(q('SELECT * FROM productos WHERE activo=1 ORDER BY nombre')->fetchAll() as $r):?><option value="<?=$r['id']?>" data-stock="<?=$r['stock']?>"><?=h($r['nombre'])?> (<?=$r['stock']?> disponibles)</option><?php endforeach;?></select></label><label>Tipo<select class="form-select" name="tipo"><option value="entrada">Entrada</option><option value="salida">Salida</option></select></label><label>Cantidad<input class="form-control" type="number" name="cantidad" min="1" step="1" required></label><label class="wide">Observación<textarea class="form-control" name="observacion" maxlength="255"></textarea></label><button class="btn btn-primary" name="accion" value="movimiento">Registrar</button></form>
<?php elseif($p==='historial'):?><h1>Historial de movimientos</h1><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Responsable</th><th>Observación</th></tr></thead><tbody><?php foreach(q('SELECT m.*,p.nombre producto,u.nombre usuario FROM movimientos m JOIN productos p ON p.id=m.producto_id JOIN usuarios u ON u.id=m.usuario_id ORDER BY m.id DESC')->fetchAll() as $r):?><tr><?php foreach(['fecha','producto','tipo','cantidad','usuario','observacion'] as $k):?><td><?=h($r[$k])?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php else: ?><p>Página no encontrada.</p><?php endif;?></main><script src="assets/validar.js"></script></body></html>
